fn delete_stream(
    &self,
    locations: BoxStream<'static, Result<Path>>,
) -> BoxStream<'static, Result<Path>> {
    let client = Arc::clone(&self.client);
    locations
        .map(move |location| {
            let client = Arc::clone(&client);
            async move {
                let location = location?;
                client.delete(&location).await?;
                Ok(location)
            }
        })
        .buffered(10)
        .boxed()
}
